import json,numpy as np
from pathlib import Path
s=json.load(open('/app/output/spec.json')); c=s['cameras']['forward']; K=np.array(c['intrinsic_cv']); M=np.array(c['cam2world_gl']); d=np.load('/app/output/descend_07/depth_forward.npy')[0]
for v in [85,90,95,100,105,110,120,130,140,150,155]:
 pts=[]
