import json,numpy as np
s=json.load(open('/app/output/spec.json')); d=np.load('/app/output/recover_lift_07/depth_forward.npy')[0]
T=np.array(s['cameras']['forward']['cam2world_gl']); K=np.array(s['cameras']['forward']['intrinsic_cv']);
def world(u,v,z):
 x=(u-K[0,2])*z/K[0,0]; y=(v-K[1,2])*z/K[1,1]
 p=T@np.array([x,-y,-z,1]);return p[:3]
def uv(p):
 gl=np.linalg.inv(T)@np.r_[p,1]; cv=np.array([gl[0],-gl[1],-gl[2]]); return (K@cv)[:2]/cv[2],cv[2]
p=np.array([-.273476,-.151854,.897650]); print('tcp proj',uv(p))
for v in [145,150,155,160,165,170,175]:
 for u in [225,230,235]: print((u,v),'d',d[v,u], 'world',world(u,v,float(d[v,u])))
